mapper.select:
select id
from practice_spaces
where slug = #{slug}

select id
from practice_activities
where slug = #{slug}

select id
from practice_phrases
where slug = #{slug}

select count(*)
from practice_spaces s
join practice_activities a on a.space_id = s.id
join practice_phrases p on p.activity_id = a.id
where s.slug = #{spaceId}
  and a.slug = #{activityId}
  and p.slug = #{phraseId}
